mapper.select:
SELECT
    (
        SELECT COUNT(1)
        FROM xianyu_order o
        WHERE o.tenant_id = #{tenantId}
          AND o.deleted = b'0'

    ) AS order_count,
    (
        SELECT COALESCE(SUM(o.pay_amount), 0)
        FROM xianyu_order o
        WHERE o.tenant_id = #{tenantId}
          AND o.deleted = b'0'

    ) AS rent_amount_fen,
    (
        SELECT COALESCE(SUM(o.refund_amount), 0)
        FROM xianyu_order o
        WHERE o.tenant_id = #{tenantId}
          AND o.deleted = b'0'

    ) AS refund_amount_fen,
    (
        SELECT COUNT(1)
        FROM rental_device d
        WHERE d.tenant_id = #{tenantId}
          AND d.deleted = b'0'
          AND DATE(d.create_time) < #{endDateExclusive}
    ) AS device_count,
    (
        SELECT COALESCE(SUM(DATEDIFF(
            #{endDateExclusive},
            GREATEST(#{startDate}, DATE(d.create_time))
        )), 0)
        FROM rental_device d
        WHERE d.tenant_id = #{tenantId}
          AND d.deleted = b'0'
          AND DATE(d.create_time) < #{endDateExclusive}
    ) AS total_device_days,
    (
        SELECT COALESCE(SUM(DATEDIFF(
            LEAST(s.occupy_end_date_exclusive, #{endDateExclusive}),
            GREATEST(s.occupy_start_date, #{startDate})
        )), 0)
        FROM rental_schedule s
        INNER JOIN rental_device d
            ON d.id = s.device_id
           AND d.tenant_id = #{tenantId}
           AND d.deleted = b'0'
        WHERE s.tenant_id = #{tenantId}
          AND s.deleted = b'0'
          AND s.status = 'EFFECTIVE'
          AND s.occupy_start_date < #{endDateExclusive}
          AND s.occupy_end_date_exclusive > #{startDate}
    ) AS occupied_device_days,
    (
        SELECT COALESCE(SUM(oi.rent_amount), 0)
        FROM rental_order_item oi
        WHERE oi.tenant_id = #{tenantId}
          AND oi.deleted = b'0'
          AND oi.billable_start_date >= #{startDate}
          AND oi.billable_start_date < #{endDateExclusive}
          AND EXISTS (
              SELECT 1
              FROM rental_device_assignment a
              WHERE a.tenant_id = #{tenantId}
                AND a.deleted = b'0'
                AND a.status = 'ASSIGNED'
                AND a.rental_order_item_id = oi.id
          )
    ) AS assigned_income_fen
